drop table if exists lot_v5_1_payloads;
create temporary table lot_v5_1_payloads as
select * from jsonb_to_recordset($raccourcia$[{"ref":"RCI-IMG-331","moteur":"chatgpt","payload":"[RaccourcIA — /customsneaker]\n\nMISSION\nCréez un design original de sneaker à partir d’une chaussure ou d’un brief. Concevoir une sneaker crédible, désirable et fabricable, avec plusieurs vues cohérentes si le contexte le permet.\n\nDÉCISION\nAnalyse le message, l’historique utile et chaque image jointe. Utilise directement l’outil d’image disponible avec les références exactes. Exécute immédiatement si le contexte suffit. Ne redemande rien de visible, fourni ou déductible avec fiabilité. Une préférence facultative ne bloque jamais la production. Si une décision indispensable reste inconnue, pose une seule question dans ce tour : Souhaitez-vous préserver entièrement la forme de la chaussure ou autoriser une nouvelle silhouette ? Puis, uniquement si encore nécessaire : Quel univers visuel doit guider la personnalisation ? Après chaque réponse, réanalyse et produis dès que le contexte suffit. Accepte « Choisis pour moi », décide professionnellement et continue. Maximum 2 questions sur toute l’exécution.\n\nEXÉCUTION\nConcevoir une sneaker crédible, désirable et fabricable, avec plusieurs vues cohérentes si le contexte le permet. Valeurs par défaut : Choix créatifs secondaires décidés automatiquement; ratio 1:1; haute définition; rendu partageable; aucun texte sauf s’il est utile et validé. Si du texte est nécessaire, utilise le texte exact fourni. Sinon choisis un mode sans texte.\n\nPRÉSERVER\nLogo fourni, proportions de la semelle, laçage, matériaux plausibles et identité de marque.\n\nÉVITER ET RESPONSABILITÉ\nMarques copiées, logos inventés, semelle impossible, détails incohérents entre les vues et texte illisible. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique, logo, identité ou événement. N’imite pas une personne publique, une marque, une franchise ou le style distinctif d’un artiste vivant. N’ajoute jamais « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Format par défaut : 1:1, haute définition. Avant de livrer, vérifie silencieusement identité ou forme du sujet, proportions, anatomie, perspective, lumière, ombres, matières, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. Si aucun outil image n’est accessible, fournis le prompt final prêt à exécuter et indique en une phrase que l’image n’a pas été générée.","sha256":"9296a2370673cd0a84e9296cd34df10483092cf974de8e9902ed70000691e23d"},{"ref":"RCI-IMG-331","moteur":"claude","payload":"[RaccourcIA — /customsneaker]\n\nMISSION\nCréez un design original de sneaker à partir d’une chaussure ou d’un brief. Concevoir une sneaker crédible, désirable et fabricable, avec plusieurs vues cohérentes si le contexte le permet.\n\nDÉCISION\nRepère d’abord les contraintes dans les images et documents, consolide-les sans longue reformulation et vérifie les capacités réellement disponibles avant de produire. Exécute immédiatement si le contexte suffit. Ne redemande rien de visible, fourni ou déductible avec fiabilité. Une préférence facultative ne bloque jamais la production. Si une décision indispensable reste inconnue, pose une seule question dans ce tour : Souhaitez-vous préserver entièrement la forme de la chaussure ou autoriser une nouvelle silhouette ? Puis, uniquement si encore nécessaire : Quel univers visuel doit guider la personnalisation ? Après chaque réponse, réanalyse et produis dès que le contexte suffit. Accepte « Choisis pour moi », décide professionnellement et continue. Maximum 2 questions sur toute l’exécution.\n\nEXÉCUTION\nConcevoir une sneaker crédible, désirable et fabricable, avec plusieurs vues cohérentes si le contexte le permet. Valeurs par défaut : Choix créatifs secondaires décidés automatiquement; ratio 1:1; haute définition; rendu partageable; aucun texte sauf s’il est utile et validé. Si du texte est nécessaire, utilise le texte exact fourni. Sinon choisis un mode sans texte.\n\nPRÉSERVER\nLogo fourni, proportions de la semelle, laçage, matériaux plausibles et identité de marque.\n\nÉVITER ET RESPONSABILITÉ\nMarques copiées, logos inventés, semelle impossible, détails incohérents entre les vues et texte illisible. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique, logo, identité ou événement. N’imite pas une personne publique, une marque, une franchise ou le style distinctif d’un artiste vivant. N’ajoute jamais « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Format par défaut : 1:1, haute définition. Avant de livrer, vérifie silencieusement identité ou forme du sujet, proportions, anatomie, perspective, lumière, ombres, matières, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. Sans moteur image connecté, livre un brief de transfert autonome, précis et exploitable. Ne prétends jamais avoir rendu ou inspecté une image inexistante.","sha256":"8974b038145e3de0ff01e67a8115085753dc39184762687a6b6ee9d4071c3ae1"},{"ref":"RCI-IMG-331","moteur":"gemini","payload":"[RaccourcIA — /customsneaker]\n\nMISSION\nCréez un design original de sneaker à partir d’une chaussure ou d’un brief. Concevoir une sneaker crédible, désirable et fabricable, avec plusieurs vues cohérentes si le contexte le permet.\n\nDÉCISION\nInspecte visuellement toutes les pièces jointes avant le texte de contexte et relie chaque référence à son rôle : sujet, style, marque, données ou composition. Exécute immédiatement si le contexte suffit. Ne redemande rien de visible, fourni ou déductible avec fiabilité. Une préférence facultative ne bloque jamais la production. Si une décision indispensable reste inconnue, pose une seule question dans ce tour : Souhaitez-vous préserver entièrement la forme de la chaussure ou autoriser une nouvelle